2266H - Deque Malfunction
Hint 1
We only need to keep one occurrence of every value $$$1,2,\ldots,n$$$. What can we do with every other occurrence?
Hint 2
Let $$$t_i$$$ be the arrival position of the occurrence of $$$i$$$ which stays in the final deque. When can $$$i$$$ be inserted without a malfunction?
Hint 3
An element can be inserted normally exactly when $$$t_i$$$ is a prefix minimum or a suffix minimum of $$$t_1,t_2,\ldots,t_n$$$.
Hint 4
Fix the position of the global minimum. The prefix minima and suffix minima can be optimized separately.
Solution
If some value from $$$1$$$ to $$$n$$$ never appears, the answer is $$$-1$$$. Otherwise, choose one occurrence of each value to keep. Every unused occurrence can simply be pushed to an end and immediately removed from that same end.
Let $$$t_i$$$ be the position of the chosen occurrence of $$$i$$$. We can push $$$i$$$ to the front normally exactly when every chosen value which arrived earlier is larger than $$$i$$$, or $$$t_i \lt \min(t_1,\ldots,t_{i-1})$$$. Similarly, we can push it to the back exactly when $$$t_i \lt \min(t_{i+1},\ldots,t_n)$$$. Thus, a value avoids a malfunction exactly when $$$t_i$$$ is a prefix minimum or a suffix minimum. The global minimum is counted in both, so if there are $$$L$$$ prefix minima and $$$R$$$ suffix minima, we keep $$$L+R-1$$$ values for free.
Now optimize the prefix minima. Process the values $$$1,2,\ldots,n$$$. Let $$$dp[p]$$$ be the maximum number of prefix minima so far when the smallest chosen arrival position is $$$p$$$. For an occurrence at position $$$t$$$, making it the new minimum gives $$$new[t]=1+\max_{p \gt t}dp[p]$$$. All of these transitions must be calculated before adding the states for the current value.
An old state with minimum $$$p$$$ can stay unchanged only if the current value has some occurrence after $$$p$$$. If $$$last_i$$$ is its last occurrence, every state with $$$p \gt last_i$$$ must therefore be deleted. For value $$$1$$$, every occurrence simply starts with value $$$1$$$.
After all values are processed, let $$$L[p]$$$ be the best number of prefix minima whose global minimum is at position $$$p$$$. Run the same DP with the values in reverse order to get $$$R[p]$$$ for suffix minima. For a fixed $$$p$$$, the two sides can be combined independently, sharing only the global minimum itself. Therefore, the maximum number of values which avoid a malfunction is $$$\max_p(L[p]+R[p]-1)$$$, and the answer is $$$n-\max_p(L[p]+R[p]-1)$$$.
Implementation 1: Lazy Segment Tree
Store the DP in a segment tree. For an occurrence $$$t$$$, the transition needs the maximum on $$$(t,m]$$$. After calculating all transitions for the current value, clear the suffix after $$$last_i$$$ and insert the new states.
A lazy segment tree supports the suffix clear and range maximum queries in $$$O(\log m)$$$, so the total complexity is $$$O(m\log m)$$$.
Code (Lazy Segment Tree)
#include <bits/stdc++.h>
using namespace std;

struct lst { //cur range add range max, change accordingly, no need for l,r in range add range mx
vector<int> seg;
vector<bool> tg;
vector<int> lz;
int sz = 1;
int id = 0; //change sent
int acc(int x, int y) {return max(x,y);} //other more complex lst can do range set and range add
void pull(int n) {seg[n]=acc(seg[n<<1],seg[(n<<1)|1]);}
void apply(int n, int l, int r, int v) {seg[n]=v; tg[n]=true; lz[n]=v;} //if something else, change id, acc, apply, and how lz accumulates/replaces in push
void push(int n, int l, int r) {if (!tg[n]) {return;} tg[n]=false; apply(n<<1,l,(l+r)/2,lz[n]); apply((n<<1)|1,(l+r)/2+1,r,lz[n]); lz[n]=0;}
lst(vector<int> A) { //inp 0 index
while (sz<A.size()) {sz<<=1;}
seg.assign(2*sz,id);
tg.assign(2*sz,false); //in case 0 is a range set
lz.assign(2*sz,0);
for (int i = 0; i < A.size(); i++) {seg[sz+i]=A[i];}
for (int i = sz-1; i >= 1; i--) {pull(i);}
}
int qq(int n, int l, int r, int sl, int sr) {
if (sl>r||sr<l) {return id;}
if (l<=sl&&sr<=r) {return seg[n];}
push(n,sl,sr);
return acc(qq(n<<1,l,r,sl,(sl+sr)/2),qq((n<<1)|1,l,r,(sl+sr)/2+1,sr));
}
void uu(int n, int l, int r, int sl, int sr, int v) {
if (sl>r||sr<l) {return;}
if (l<=sl&&sr<=r) {apply(n,sl,sr,v); return;}
push(n,sl,sr);
uu(n<<1,l,r,sl,(sl+sr)/2,v);
uu((n<<1)|1,l,r,(sl+sr)/2+1,sr,v);
pull(n);
}
int q(int l, int r) {return qq(1,l,r,1,sz);}
void u(int l, int r, int v) {uu(1,l,r,1,sz,v);}
};

void solve() {
int N, M; cin >> N >> M;
vector<int> A;
for (int i = 0; i < N; i++) {
A.push_back(i+1);
}
vector<vector<int>> tt(N+1);
vector<int> ndp1(M+1);
for (int i = 1; i <= M; i++) {
int a; cin >> a;
tt[a].push_back(i);
}
for (int i = 1; i <= N; i++) {
if (tt[i].empty()) {cout << -1 << endl; return;}
}
vector<int> ii(M+1); // one sentinel at end so no RE
lst dp1(ii);
bool f = true;
for (auto x : A) {
for (auto t : tt[x]) {
int rr = dp1.q(t+1,M+1);
ndp1[t]=(rr?rr+1:rr+(f));
}
for (auto t : tt[x]) {
dp1.u(t,t,ndp1[t]);
}
dp1.u(tt[x].back()+1,M+1,0);
if (f) {f=false;}
}
vector<int> ndp2(M+1);
reverse(A.begin(),A.end());
lst dp2(ii);
f=true;
for (auto x : A) {
for (auto t : tt[x]) {
int rr = dp2.q(t+1,M+1);
ndp2[t]=(rr?rr+1:rr+(f));
}
for (auto t : tt[x]) {
dp2.u(t,t,ndp2[t]);
}
dp2.u(tt[x].back()+1,M+1,0);
if (f) {f=false;}
}
int aa = 0;
for (int i = 1; i <= M; i++) {aa=max(aa,dp1.q(i,i)+dp2.q(i,i)-1);}
cout << N-aa << endl;
}

int main() {
int T; cin >> T;
while (T--) {solve();}
}

Implementation 2: Amortized Set Deletion
We can also use a normal segment tree together with a set of active positions. Whenever a state with position greater than $$$last_i$$$ becomes invalid, remove the largest such position from the set and set its segment tree value to $$$0$$$.
Each position is inserted once and deleted at most once in one pass, so there are only $$$O(m)$$$ deletions in total. The total complexity is again $$$O(m\log m)$$$.
Code (Amortized Set Deletion)
#include <bits/stdc++.h>
using namespace std;

struct tri { //inp zero index vector, transformed to 1 index
vector<int> s;
int sz = 1;
tri(vector<int> &A) {
while (sz<A.size()) {sz<<=1;}
s.assign(2*sz,0);
for (int i = 0; i < A.size(); i++) {s[i+sz] = A[i];}
for (int i = sz-1; i >= 1; i--) {s[i]=max(s[i<<1],s[(i<<1)|1]);}
}
void u(int i, int x) {
int p = sz+i-1; s[p] = x;
for (p>>=1; p; p>>=1) {s[p]=max(s[p<<1],s[(p<<1)|1]);}
}
int aa(int n, int l, int r, int sl, int sr) {
if (l<=sl&&sr<=r) {return s[n];}
else if (sr<l||sl>r) {return 0;}
else {return max(aa(n<<1,l,r,sl,(sl+sr)>>1),aa((n<<1)|1,l,r,((sl+sr)>>1)+1,sr));}
}
int q(int l, int r) {return aa(1,l,r,1,sz);}
};

void solve() {
int N, M; cin >> N >> M;
vector<int> A;
for (int i = 0; i < N; i++) {
A.push_back(i+1);
}
vector<vector<int>> tt(N+1);
vector<int> ndp1(M+1);
for (int i = 1; i <= M; i++) {
int a; cin >> a;
tt[a].push_back(i);
}
for (int i = 1; i <= N; i++) {
if (tt[i].empty()) {cout << -1 << endl; return;}
}
vector<int> ii(M+1); // one sentinel at end so no RE
tri dp1(ii);
set<int> act;
bool f = true;
for (auto x : A) {
for (auto t : tt[x]) {
int rr = dp1.q(t+1,M+1);
ndp1[t]=(rr?rr+1:rr+(f));
}
for (auto t : tt[x]) {
dp1.u(t,ndp1[t]);
act.insert(t);
}
while (!act.empty()&&(*act.rbegin()>tt[x].back())) {dp1.u((*act.rbegin()),0); act.erase(*act.rbegin());}
if (f) {f=false;}
}
vector<int> ndp2(M+1);
act.clear();
reverse(A.begin(),A.end());
tri dp2(ii);
f=true;
for (auto x : A) {
for (auto t : tt[x]) {
int rr = dp2.q(t+1,M+1);
ndp2[t]=(rr?rr+1:rr+(f));
}
for (auto t : tt[x]) {
dp2.u(t,ndp2[t]);
act.insert(t);
}
while (!act.empty()&&(*act.rbegin()>tt[x].back())) {dp2.u((*act.rbegin()),0); act.erase(*act.rbegin());}
if (f) {f=false;}
}
int aa = 0;
for (int i = 1; i <= M; i++) {aa=max(aa,dp1.q(i,i)+dp2.q(i,i)-1);}
cout << N-aa << endl;
}

int main() {
int T; cin >> T;
while (T--) {solve();}
}

